import { useEffect, useState } from 'react'
import { useParams, Link } from 'react-router-dom'
import { useDispatch, useSelector } from 'react-redux'
import { PayPalButtons, PayPalScriptProvider } from '@paypal/react-paypal-js'
import { Container, Row, Col, ListGroup, Alert, Button } from 'react-bootstrap'
import { getOrderDetails, payOrder } from '../actions/orderActions'

const OrderScreen = () => {
  const { id } = useParams()
  const dispatch = useDispatch()
  const [sdkReady, setSdkReady] = useState(false)

  const orderDetails = useSelector(state => state.orderDetails)
  const { order, loading, error } = orderDetails

  const orderPay = useSelector(state => state.orderPay)
  const { loading: loadingPay, success: successPay } = orderPay

  useEffect(() => {
    if (!order || order._id !== id || successPay) {
      dispatch(getOrderDetails(id))
    }
  }, [dispatch, id, order, successPay])

  // Adicionar script do PayPal dinamicamente (opcional, mas o SDK Provider já faz)
  useEffect(() => {
    const addPayPalScript = () => {
      const script = document.createElement('script')
      script.src = `https://www.paypal.com/sdk/js?client-id=${process.env.REACT_APP_PAYPAL_CLIENT_ID}`
      script.async = true
      script.onload = () => setSdkReady(true)
      document.body.appendChild(script)
    }
    if (!window.paypal) addPayPalScript()
    else setSdkReady(true)
  }, [])

  if (!order) return <div>Carregando...</div>

  const addDecimals = (num) => (Math.round(num * 100) / 100).toFixed(2)

  return (
    <Container className="py-4">
      <h1>Pedido {order._id}</h1>
      {loading ? <p>Carregando...</p> : error ? <Alert variant="danger">{error}</Alert> : (
        <Row>
          <Col md={8}>
            <ListGroup variant="flush">
              <ListGroup.Item>
                <h2>Entrega</h2>
                <p><strong>Endereço:</strong> {order.shippingAddress.address}, {order.shippingAddress.city}</p>
                {order.isDelivered ? <Alert variant="success">Entregue em {order.deliveredAt}</Alert> : <Alert variant="warning">Não entregue</Alert>}
              </ListGroup.Item>
              <ListGroup.Item>
                <h2>Pagamento</h2>
                <p><strong>Método:</strong> {order.paymentMethod}</p>
                {order.isPaid ? <Alert variant="success">Pago em {order.paidAt}</Alert> : <Alert variant="warning">Não pago</Alert>}
              </ListGroup.Item>
              <ListGroup.Item>
                <h2>Itens</h2>
                {order.orderItems.map((item, idx) => (
                  <div key={idx}>
                    {item.name} x {item.qty} = R$ {item.price * item.qty}
                  </div>
                ))}
              </ListGroup.Item>
            </ListGroup>
          </Col>
          <Col md={4}>
            <ListGroup variant="flush">
              <ListGroup.Item><h2>Resumo</h2></ListGroup.Item>
              <ListGroup.Item>Itens: R$ {order.itemsPrice}</ListGroup.Item>
              <ListGroup.Item>Frete: R$ {order.shippingPrice}</ListGroup.Item>
              <ListGroup.Item>Impostos: R$ {order.taxPrice}</ListGroup.Item>
              <ListGroup.Item><strong>Total: R$ {order.totalPrice}</strong></ListGroup.Item>
              {!order.isPaid && (
                <ListGroup.Item>
                  {loadingPay && <p>Processando pagamento...</p>}
                  {!sdkReady ? (
                    <p>Carregando PayPal...</p>
                  ) : (
                    <PayPalScriptProvider options={{ "client-id": "SEU_CLIENT_ID_AQUI" }}>
                      <PayPalButtons
                        createOrder={(data, actions) => {
                          return actions.order.create({
                            purchase_units: [{ amount: { value: order.totalPrice } }]
                          })
                        }}
                        onApprove={(data, actions) => {
                          return actions.order.capture().then(details => {
                            const paymentResult = {
                              id: details.id,
                              status: details.status,
                              update_time: details.update_time,
                              email_address: details.payer.email_address
                            }
                            dispatch(payOrder(order._id, paymentResult))
                          })
                        }}
                      />
                    </PayPalScriptProvider>
                  )}
                </ListGroup.Item>
              )}
            </ListGroup>
          </Col>
        </Row>
      )}
    </Container>
  )
}

export default OrderScreen
